<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed,watch,nextTick} from 'vue'
import ImageEditor from './ImageEditor.vue'
import Portrait from './Portrait.vue'
import CatalogPanel from './CatalogPanel.vue'
import {personState,profile} from './people'
const props=defineProps<{project:Record<string,any>}>();const emit=defineEmits(['replace','running'])
const status=ref<any>({}),tasks=ref<any[]>([]),busy=ref(false),error=ref(''),message=ref(''),documentId=ref(''),page=ref(1),pages=ref('1'),target=ref('background'),selected=ref(''),zoom=ref(100)
const removeOpen=ref(false)
const toolsOpen=ref(false),editing=ref(false),showHotspots=ref(true),detailTab=ref('profile'),search=ref('')
const activePerson=computed(()=>people.value.find((a:any)=>a.id===selected.value))
const visiblePeople=computed(()=>people.value.filter((a:any)=>(character(a)?.name||'未命名人物').includes(search.value.trim())))
const selectedCharacter=computed(()=>activePerson.value?character(activePerson.value):null)
const mode=ref('explore'),names=ref<Record<string,string>>({}),duplicates=ref<Record<string,boolean>>({}),candidateReview=ref(false),catalogRunning=ref(false)
const kinds:Record<string,string>={background:'历史背景',relationships:'人物与关系',narrative:'已有历史叙事（选填）'}
const doc=computed(()=>props.project.documents?.find((d:any)=>d.id===documentId.value))
const people=computed(()=>props.project.annotations.filter((a:any)=>a.kind==='character'))
const submittedPersonTasks=ref<string[]>([])
const personTask=computed(()=>tasks.value.find(t=>['detect','match'].includes(t.kind)&&(['queued','running'].includes(t.status)||submittedPersonTasks.value.includes(t.id))))
const narrativeMode=computed(()=>props.project.materialInputs.narrative.trim()?'保留已有历史叙事框架':'基于历史背景共创故事')
let timer:ReturnType<typeof setInterval>|undefined;let mounted=true;let polling=false
async function request(path:string,method='GET',body?:any){const r=await fetch('/api'+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body instanceof FormData?body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok){const err:any=Error(typeof v.detail==='string'?v.detail:v.detail?.message||JSON.stringify(v.detail));err.detail=v.detail;throw err;}return v}
async function save(){const p=await request('/projects/'+props.project.id,'PUT',props.project);emit('replace',p);return p}
async function poll(){if(polling)return;polling=true;try{const previous=tasks.value;const rows=await request(`/projects/${props.project.id}/tasks`);if(!mounted)return;tasks.value=rows;if(tasks.value.some(t=>t.applied&&!previous.find(v=>v.id===t.id)?.applied)){emit('replace',await request('/projects/'+props.project.id));if(tasks.value.some(t=>t.kind==='people_analysis'&&t.applied&&!previous.find(v=>v.id===t.id)?.applied))showHotspots.value=true;}status.value=await request('/status')}catch(e){if(mounted)error.value=String(e)}finally{polling=false}}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function check(kind:string){await run(async()=>{const r=await request('/models/check','POST',{kind});message.value=r.ok?'连接成功':'未返回有效结果'})}
async function task(kind:string,extra?:any){await run(async()=>{const p=await save();const submitted=await request(`/projects/${p.id}/tasks`,'POST',{version:p.version,kind,documentId:documentId.value,pages:pages.value.split(',').map(v=>Number(v.trim())).filter(v=>Number.isInteger(v)&&v>0),trigger:'user_button',...extra});tasks.value.unshift(submitted);if(['detect','match'].includes(kind))submittedPersonTasks.value.push(submitted.id);await poll()})}
async function runPersonTask(kind:string){if(running.value)return;showHotspots.value=true;editing.value=false;mode.value='explore';await task(kind)}
async function upload(e:Event,type:string){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;await run(async()=>{const p=await save();const form=new FormData();form.append('file',f);emit('replace',await request(`/projects/${p.id}/${type}?version=${p.version}`,'POST',form));await poll()})}
async function adopt(legacy=false,updateIds:string[]=[]){await run(async()=>{const p=await save();emit('replace',await request(`/projects/${p.id}/materials/adopt`,'POST',{version:p.version,legacy,updateIds}));message.value='已采用建议，原资料及稳定角色ID保留';candidateReview.value=false})}
function changed(id:string){const a=props.project.annotations.find((a:any)=>a.id===id);if(a){a.confirmed=false;a.identityConfirmed=false;a.needsReview=true}for(const o of props.project.observations.filter((o:any)=>o.annotationId===id)){o.confirmed=false;o.stale=true}for(const m of props.project.matches.filter((m:any)=>m.annotationId===id)){m.confirmed=false;m.stale=true}}
function observation(a:any){return props.project.observations.find((o:any)=>o.annotationId===a.id)}
function match(a:any){return props.project.matches.find((m:any)=>m.annotationId===a.id)}
function choose(a:any){const m=match(a);if(m){m.characterId=a.characterId;m.confirmed=false;m.manual=true;m.stale=false}a.identityConfirmed=false;a.needsReview=true}
async function confirm(a:any){await run(async()=>{const p=await save();emit('replace',await request(`/projects/${p.id}/people/${a.id}/confirm`,'POST',{version:p.version,characterId:a.characterId}));message.value='人物资料与姓名对应已确认并保存'})}
function character(a:any){return props.project.characters.find((c:any)=>c.id===a.characterId)}
async function namePerson(a:any,useExisting=false){await run(async()=>{const p=await save();try{emit('replace',await request(`/projects/${p.id}/people/${a.id}/name`,'POST',{version:p.version,name:names.value[a.id]||'',useExisting}));duplicates.value[a.id]=false;names.value[a.id]=''}catch(e:any){if(e.detail?.code==='name_exists'){duplicates.value[a.id]=true;message.value=e.detail.message}else throw e}})}

function confirmObservation(a:any){const o=observation(a);if(o){o.confirmed=a.confirmed;o.description=a.description;o.stale=false}}
function editMaterial(){props.project.materialAnalysis.stale=true}
function insert(text:string){const old=props.project.materialInputs[target.value];props.project.materialInputs[target.value]=old+(old.trim()?'\n\n':'')+text;editMaterial();message.value='已放入选定输入框，尚未调用模型'}
async function removeVisiblePerson(){const aid=selected.value;if(!aid)return;await run(async()=>{const p=await save();emit('replace',await request('/projects/'+p.id+'/people/'+aid+'/remove','POST',{version:p.version}));selected.value='';removeOpen.value=false;message.value='人物标注已移除，相关场景引用已更新；原有正文请重新核对'})}
function select(id:string,fromCard=false){removeOpen.value=false;if(id!==selected.value)detailTab.value='profile';selected.value=id}
const running=computed(()=>busy.value||catalogRunning.value||tasks.value.some(t=>['queued','running'].includes(t.status)))
watch(running,v=>emit('running',v),{immediate:true})
watch(toolsOpen,async open=>{if(open){await nextTick();document.getElementById('artwork-library')?.scrollIntoView({block:'start',behavior:'smooth'})}})
onMounted(()=>{poll();timer=setInterval(poll,2500)});onUnmounted(()=>{mounted=false;clearInterval(timer);emit('running',false)})
</script>
<template>
<div v-if="error" class="banner error" role="alert">{{error}}</div><div v-if="message" class="banner">{{message}}</div>
<section class="explore-heading"><div><small>EXPLORE THE PAINTING</small><h2>画作探索</h2><p>从画中人物出发，读懂画面背后的故事。</p></div><button class="tools-button" :aria-expanded="toolsOpen" @click="toolsOpen=!toolsOpen">画作资料库 <span>{{toolsOpen?'−':'＋'}}</span></button></section>
<section class="context-strip"><span class="context-icon">卷</span><div><b>{{project.title}}</b><span>已载入 {{project.sources.length}} 份资料 · {{people.length}} 个人物标注</span></div><details><summary>阅读作品背景</summary><div class="context-popover"><h3>作品与历史背景</h3><p class="pre">{{project.materialInputs.background||'尚无作品背景，可在画作资料库中补充。'}}</p><small>以下资料来自当前项目，身份判断请结合原文核查。</small></div></details></section>
<div class="explore-layout">
<article class="painting-panel"><div class="painting-heading"><div><h3>画作全览</h3><small>{{editing?'修正模式 · 调整标注后请保存':'点击画中标注，探索人物与史料'}}</small></div><div class="painting-actions"><button class="analyze-button" :disabled="running||!project.image" @click="runPersonTask('detect')">{{people.length?'重新检测人物框':'检测人物框'}}</button><button class="primary analyze-button" :disabled="running||!people.length||!project.characters.length" @click="runPersonTask('match')">匹配姓名</button><button class="quiet-button" :aria-pressed="showHotspots" @click="showHotspots=!showHotspots">{{showHotspots?'◉ 隐藏标注':'◎ 显示标注'}}</button></div></div>
<div v-if="!project.characters.length" class="analysis-guidance">请先在画作资料库添加人物档案。</div>
<div v-if="personTask" class="person-task-status" :class="personTask.status" role="status" aria-live="polite"><span v-if="['queued','running'].includes(personTask.status)" class="task-spinner"/><span>{{personTask.progress}}</span><button v-if="['failed','stale','interrupted'].includes(personTask.status)" :disabled="running" @click="runPersonTask(personTask.kind)">重试本步骤</button></div>
<div class="explore-canvas" :class="{'hide-hotspots':!showHotspots,'is-exploring':!editing}">
<ImageEditor v-if="project.image" :project="project" :zoom="zoom" :selected-id="selected" :disabled="running" :mode="mode" @added="mode='select'" @select="select($event)" @changed="changed"/>
<div v-else class="canvas-empty"><span>山</span><h3>从一幅画开始</h3><p>当前项目还没有画作，请在“画作资料库”的导入工具中上传。</p><button @click="toolsOpen=true">上传画作</button></div></div>
<div class="canvas-controls"><span>拖动画面平移 · 点击标注查看人物</span><div><button aria-label="缩小画作" :disabled="zoom<=50" @click="zoom=Math.max(50,zoom-25)">−</button><output>{{zoom}}%</output><button aria-label="放大画作" :disabled="zoom>=300" @click="zoom=Math.min(300,zoom+25)">＋</button><button @click="zoom=100">适应画布</button></div></div>
<div v-if="editing" class="correction-toolbar"><span>修正人物标注</span><button :class="{active:mode==='select'}" @click="mode='select'">调整框</button><button :class="{active:mode==='add'}" @click="mode='add';showHotspots=true">补充人物</button><button :disabled="running||!selected" @click="removeOpen=true">移除此人物标注</button><button :disabled="running" @click="run(async()=>{await save();editing=false;mode='explore';message='修正已保存'})">保存修正</button></div>
<div class="people-ribbon"><div class="ribbon-heading"><h3>画中人物 <span>{{people.length}}</span></h3><input v-model="search" aria-label="查找画中人物" placeholder="查找人物…"></div><div class="portrait-list"><button v-for="(a,i) in visiblePeople" :key="a.id" :class="{chosen:selected===a.id}" :aria-pressed="selected===a.id" @click="select(a.id,true);showHotspots=true"><Portrait :url="project.image" :box="a"/><span>{{character(a)?.name||'未命名人物 '+(people.indexOf(a)+1)}}</span><small :class="personState(project,a).key">● {{personState(project,a).label}}</small></button><p v-if="!visiblePeople.length">{{search?'未找到匹配的人物。':'尚无人物标注，点击“检测人物框”，再按需匹配姓名。'}}</p></div></div>
</article>
<aside class="person-detail"><template v-if="activePerson"><div class="detail-heading"><small>人物 {{String(people.indexOf(activePerson)+1).padStart(2,'0')}} / {{String(people.length).padStart(2,'0')}}</small><button aria-label="关闭人物详情" @click="select('')">×</button></div><div class="person-intro"><Portrait :url="project.image" :box="activePerson"/><div><span class="status-pill" :class="personState(project,activePerson).key">{{personState(project,activePerson).label}}</span><h2>{{selectedCharacter?.name||'未命名人物'}}</h2><p>{{selectedCharacter?.identity||'身份尚未确定'}}</p></div></div>
<div class="detail-tabs" role="tablist" aria-label="人物详情"><button v-for="(label,key) in {profile:'人物资料',visual:'画面观察',sources:'史料依据'}" :key="key" role="tab" :aria-selected="detailTab===key" :class="{active:detailTab===key}" @click="detailTab=key">{{label}}</button></div>
<div class="detail-body" role="tabpanel"><template v-if="detailTab==='profile'"><small class="section-kicker">人物简介</small><p>{{profile(selectedCharacter)}}</p><template v-if="selectedCharacter?.relationships"><h3>人物关系</h3><p>{{selectedCharacter.relationships}}</p></template><div class="reading-note"><span>读画提示</span><p>人物资料来自项目文献；画中姓名对应仍需结合画面核对。未确认的推测不会视为历史事实。</p></div><button class="text-button" @click="detailTab='sources'">查看原文依据 →</button></template>
<template v-if="detailTab==='visual'"><small class="section-kicker">可见特征 · {{activePerson.confirmed?'已确认':'待核查'}}</small><p>{{activePerson.description||'尚无画面观察。'}}</p><details v-if="observation(activePerson)?.inference"><summary>查看视觉推测</summary><p>{{observation(activePerson).inference}}</p><small>视觉推测不作为历史依据。</small></details><details v-if="match(activePerson)"><summary>查看身份匹配理由</summary><p>{{match(activePerson).reason}}</p></details></template>
<template v-if="detailTab==='sources'"><small class="section-kicker">资料与出处</small><p>{{selectedCharacter?.evidence||'当前人物尚无已关联的原文依据。'}}</p><div v-for="(m,i) in selectedCharacter?.mentions||[]" :key="i" class="source-excerpt"><small>{{kinds[m.kind]||'原文'}} · {{m.start}}–{{m.end}} · v{{m.sourceVersion}}</small><blockquote>{{m.quote}}</blockquote></div><details v-if="project.materialInputs.relationships"><summary>人物与关系原文</summary><p class="pre">{{project.materialInputs.relationships}}</p></details><details v-if="project.materialInputs.narrative"><summary>历史叙事原文</summary><p class="pre">{{project.materialInputs.narrative}}</p></details><details v-for="s in project.sources.filter((s:any)=>s.method!=='material_input')" :key="s.id"><summary>{{s.title}}</summary><p class="pre">{{s.text}}</p><small>{{s.citation||'未提供出处'}} · v{{s.version}}</small></details></template></div>
<div v-if="editing" class="correction-form"><h3>修正人物信息</h3><label>对应人物<select v-model="activePerson.characterId" @change="choose(activePerson)"><option value="">未确定／资料未提及</option><option v-for="c in project.characters" :key="c.id" :value="c.id">{{c.name}}</option></select></label><details><summary>资料未覆盖？直接命名</summary><input v-model="names[activePerson.id]" placeholder="姓名或角色称谓"><button :disabled="running||!names[activePerson.id]?.trim()" @click="namePerson(activePerson)">创建并关联</button><button v-if="duplicates[activePerson.id]" :disabled="running" @click="namePerson(activePerson,true)">关联已有同名角色</button></details><label>画面观察<textarea v-model="activePerson.description" @input="activePerson.confirmed=false;confirmObservation(activePerson)"/></label><label><input type="checkbox" v-model="activePerson.confirmed" @change="confirmObservation(activePerson)"> 确认画面观察</label><button class="primary" :disabled="running||!activePerson.characterId" @click="confirm(activePerson)">核对并确认此人物</button><button class="remove-person-button" :disabled="running" @click="removeOpen=true">移除此人物标注</button><div v-if="removeOpen" class="remove-person-confirm"><p>认为画中没有此人物？将移除当前标注；若这是该人物的唯一标注，也会移除其人物卡片及场景关联。原有正文保留，需重新核对。</p><button :disabled="running" @click="removeVisiblePerson">确认移除</button><button :disabled="running" @click="removeOpen=false">取消</button></div></div>
<div class="detail-bottom"><button :disabled="running" @click="editing=!editing;mode=editing?'select':'explore';showHotspots=true">{{editing?'退出修正':'修正人物信息'}} <span>↗</span></button></div></template>
<div v-else class="unselected-detail"><div class="empty-symbol">人</div><small>从一个人物开始</small><h2>画中人，画外事。</h2><p>点击画面中的人物标注，<br>或从下方人物列表中选择。<br>在这里查看人物、观察与史料。</p><div class="explore-hint"><span>01</span> 选中画中人物</div><div class="explore-hint"><span>02</span> 阅读人物与画面细节</div><div class="explore-hint"><span>03</span> 展开史料，核对依据</div><button v-if="project.image&&!people.length" @click="editing=true;mode='add';showHotspots=true">手动补充人物标注</button></div>
</aside></div>
<div v-if="toolsOpen" id="artwork-library" class="tools-drawer"><CatalogPanel :project="project" :analysis-running="running" :relation-task="tasks.find(t=>t.kind==='relations_analysis')" @analyze-relations="task('relations_analysis')" @replace="emit('replace',$event)" @running="catalogRunning=$event" @close="toolsOpen=false"/><details class="advanced-tools"><summary>导入与分析工具</summary><div class="tools-heading"><div><h2>导入与分析工具</h2><p>补充原始材料，或按需运行分析。</p></div><button @click="toolsOpen=false">收起 ↑</button></div>
<article class="analysis-tools"><h3>画作管理</h3><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="running" @change="upload($event,'image')"><div class="actions"><button :disabled="running||!project.image" @click="task('detect')">检测人物 · 本地模型</button><button :disabled="running||!people.length||!project.characters.length" @click="task('vision_match')">分析外观并建议身份 · 调用 LLM</button><button :disabled="running||!project.image" @click="editing=true;mode='add';showHotspots=true;toolsOpen=false">手动补充人物</button></div><small>模型仅在点击按钮后调用；浏览与选择人物不调用模型。</small></article>
<details class="legacy-materials"><summary>批量资料输入与模型整理（高级）</summary><article class="materials"><h2>原始资料与整理</h2><div class="material-grid"><label v-for="(name,key) in kinds">{{name}}<textarea rows="9" v-model="project.materialInputs[key]" @input="editMaterial" :placeholder="key==='narrative'?'如果画作有史料记载的故事，请填入事件经过；没有可留空。':'整段粘贴资料，可将出处和链接一并写入。'"/></label></div><div class="actions"><button class="primary" :disabled="running" @click="task('materials')">整理资料并提取人物 · 调用 LLM</button><span class="mode">{{narrativeMode}}</span></div><small>填写已有叙事表示你提供了历史故事框架，不代表系统已经独立核实。留空时，新增故事事件属于共创内容。</small>
<div v-if="project.materialAnalysis.summary" class="card"><p>{{project.materialAnalysis.summary}}</p><small v-if="project.materialAnalysis.stale">资料已变化，旧整理结果待复核。点击按钮重新整理。</small><details><summary>查看整理结果与原文片段</summary><p v-for="event in project.materialAnalysis.eventFramework">{{event}}</p><p v-for="s in project.materialSegments"><b>{{kinds[s.kind]}}</b> · {{s.summary}}<small>原文位置 {{s.start}}–{{s.end}} · v{{s.sourceVersion}}</small><q>{{s.quote}}</q></p></details><button :disabled="running||project.materialAnalysis.stale" @click="candidateReview=!candidateReview">查看人物候选差异并采用</button><div v-if="candidateReview"><div v-for="c in project.materialAnalysis.characters" class="card"><b>{{c.name}}</b><p>{{profile(c)}}</p><template v-if="project.characters.some((v:any)=>v.name===c.name)"><small>现有：{{profile(project.characters.find((v:any)=>v.name===c.name))}}</small><button @click="adopt(false,[project.characters.find((v:any)=>v.name===c.name).id])">采用此人物更新（保留ID）</button></template><small v-else>新增候选人物</small></div><button @click="adopt()">只补充新增人物，保留已有资料</button></div></div>
<details v-if="project.sources.some((s:any)=>s.method!=='material_input')"><summary>旧资料与文件原文（保留引用）</summary><button :disabled="running" @click="task('legacy_materials')">整理旧资料到三段输入 · 调用 LLM</button><details v-for="s in project.sources.filter((s:any)=>s.method!=='material_input')" class="card"><summary>{{s.title}}</summary><p class="pre">{{s.text}}</p><small>{{s.citation}}</small></details></details>
<div v-if="project.legacyMaterialProposal" class="card"><h3>三段输入建议</h3><p v-for="(name,key) in kinds"><b>{{name}}</b><br>{{project.legacyMaterialProposal[key]}}</p><small>采用将替换当前三段输入；旧资料和旧引用仍然保留。</small><button @click="adopt(true)">采用这三段建议</button></div>
</article></details>
<details class="document-tools"><summary>从文件辅助填入资料／扫描页 OCR</summary><article><input type="file" accept=".txt,.md,.pdf,.png,.jpg,.jpeg,.webp" @change="upload($event,'documents')"><select v-model="documentId" @change="page=1"><option value="">选择已导入文件</option><option v-for="d in project.documents" :value="d.id">{{d.title}}（{{d.pageCount}}页）</option></select><template v-if="doc"><label>预览页码<input type="number" min="1" :max="doc.pageCount" v-model="page"></label><div class="document-grid"><div><iframe v-if="doc.format==='text'" :src="`/api/projects/${project.id}/documents/${doc.id}/pages/1`" title="原文"/><img v-else class="page-preview" :src="`/api/projects/${project.id}/documents/${doc.id}/pages/${page}`"></div><div><label>放入哪个输入框<select v-model="target"><option v-for="(name,key) in kinds" :value="key">{{name}}</option></select></label><div v-for="s in project.sources.filter((s:any)=>s.documentId===doc.id&&s.page===Number(page))"><textarea rows="10" v-model="s.text"/><button @click="insert(s.text)">将此页文本放入选定输入框</button></div><template v-if="doc.format!=='text'"><label>识别页码（逗号分隔，最多20页）<input v-model="pages"></label><small>将执行最多 {{pages.split(',').filter(v=>v.trim()).length}} 次视觉调用，需校对原页。</small><button :disabled="running" @click="task('ocr')">OCR 识别所选页 · 调用 LLM</button></template></div></div></template></article></details>
<div v-for="t in tasks.slice(0,4)" class="task-row"><b>{{({relations_analysis:'史料关系分析',people_analysis:'人物分析',materials:'资料整理',legacy_materials:'旧资料整理',vision_match:'外观与身份分析',detect:'人物检测',ocr:'文字识别'} as Record<string,string>)[t.kind]||t.kind}}</b> · {{t.progress}}<button v-if="['failed','stale','interrupted'].includes(t.status)" :disabled="running" @click="task(t.kind,{documentId:t.request.documentId,pages:t.request.pages})">重试 · {{t.kind==='detect'?'本地模型':'调用 LLM'}}</button></div>
<details class="settings"><summary>模型设置与连通性测试</summary><small>服务 {{status.provider||'未配置'}} · 文本 {{status.textModel}} · 视觉 {{status.visionModel}} · 检测器 {{status.detectorLoaded?'已加载':status.detectorCached?'已缓存':'未加载'}}。测试按钮会发送真实请求。</small><div class="actions"><button @click="check('text')">测试文本模型 · 调用 API</button><button @click="check('vision')">测试视觉模型 · 调用 API</button></div></details>
</details></div>
